Component(
  dsl: 1, id: "example/menu-page", name: "MenuPage", kind: Kind.section,
  description: "Page-owned state controlled through callback props.",
  states: [
    BoolState(name: "menuOpen", default: false),
    StringState(name: "selected", default: "none"),
  ],
  variants: [Variant(id: "default", label: "Default", build:
    Stack(children: [
      Scaffold(
        appBar: Box(height: 64, background: Color.surface, child:
          MenuHeader(
            open: state.menuOpen,
            onToggle: Toggle(state: "menuOpen"),
            onSelect: Actions(actions: [
              SetState(state: "selected", value: event.value),
              SetState(state: "menuOpen", value: false),
            ]),
          )
        ),
        body: Text(child: "Selected: ${state.selected}"),
      ),
      Positioned(top: 64, right: 8, width: 220, child:
        If(condition: state.menuOpen, then:
          Box(background: Color.surface, padding: Space.md, child:
            Column(gap: Space.sm, children: [
              Text(child: "Dropdown content"),
              Button(label: "Dismiss dropdown", onTap: SetState(state: "menuOpen", value: false)),
            ])
          )
        )
      ),
    ])
  )],
)

